#!/usr/bin/env bash
# Regenerates the pinned libdrm subset in this directory from upstream.
#
# Every file except xf86drm.c is a byte-for-byte upstream copy, checked
# against the SHA-256 recorded below. xf86drm.c is the upstream licence block
# plus the line ranges in RANGES, copied verbatim behind a fixed include
# preamble (README.md lists what each range holds). Moving a pin is a
# deliberate edit: update the commit, the hashes and, for libdrm, the ranges.
#
# Usage: bash third_party/libdrm/update.sh [scratch-dir]
set -euo pipefail

LIBDRM_REPO="https://gitlab.freedesktop.org/mesa/libdrm.git"
LIBDRM_PIN="33fab8cbca7f7581e955a675597d14412702edc4"
LINUX_PIN="05441d697f7f9a927264f4058cbbc6a03dfcac9d"
XE_DRM_URL="https://raw.githubusercontent.com/torvalds/linux/$LINUX_PIN/include/uapi/drm/xe_drm.h"

# upstream path → sha256 at the pin
declare -A SHA256=(
    [xf86drm.c]=ad1ba6cf51127e196b67b96314ffdc3d6a4cb36bcf3e961965331b714cd7e706
    [xf86drm.h]=898987f2b0e3188b3acc1edc0131b7de6d325fd2001327d2762b650339f1b069
    [libdrm_macros.h]=e46bbea5a867b9ecf6cba55e39306c477bae3fa503ef7677648734386d694125
    [include/drm/drm.h]=f9eadbfa0f9e1aeacc27f5c931ca3bd7b46974dbad817cd02fe601ccb5cdf08d
    [include/drm/drm_mode.h]=ee4068c026dfb6c85c668cb4e41ff9cbf30e99c10c5e7ef2ad1c7870d3f9a3bf
    [LICENSES/MIT.txt]=4af446c9157f0b0826ce5d83d1722a8b28cac398bff91e982f92951821827155
    [xe_drm.h]=a8aab5a3fa5370c338b101fe9086ae83f5649bc11b71a04569247158f752ac70
)

# xf86drm.c line ranges kept (inclusive), in file order.
RANGES=(
    1-13        # licence block
    103-103     # memclear
    105-105     # drm_server_info (never set: drmSetServerInfo is not kept)
    627-649     # drmDebugPrint, drmMsg
    658-680     # drmMalloc, drmFree, drmIoctl
    1280-1391   # drmFreeVersion, drmFreeKernelVersion, drmCopyVersion, drmGetVersion
    1428-1442   # drmGetCap
    3351-3382   # drmPrimeHandleToFD, drmPrimeFDToHandle
    4957-5194   # drmSyncobj*
)

HERE="$(cd "$(dirname "$0")" && pwd)"
SCRATCH="${1:-$(mktemp -d)}"
SRC="$SCRATCH/libdrm"

if [[ ! -d "$SRC/.git" ]]; then
    git init -q "$SRC"
    git -C "$SRC" remote add origin "$LIBDRM_REPO"
fi
if ! git -C "$SRC" cat-file -e "$LIBDRM_PIN^{commit}" 2>/dev/null; then
    git -C "$SRC" fetch -q --depth 1 origin "$LIBDRM_PIN"
fi
git -C "$SRC" checkout -q -f "$LIBDRM_PIN"
curl -sSfL -o "$SCRATCH/xe_drm.h" "$XE_DRM_URL"

check() {
    local file="$1" key="$2" got
    got="$(sha256sum "$file" | cut -d' ' -f1)"
    [[ "$got" == "${SHA256[$key]}" ]] || { echo "FAIL: $key sha256 $got != ${SHA256[$key]}" >&2; exit 1; }
}
UPSTREAM_COPIES=(xf86drm.h libdrm_macros.h include/drm/drm.h include/drm/drm_mode.h LICENSES/MIT.txt)
check "$SRC/xf86drm.c" xf86drm.c
for key in "${UPSTREAM_COPIES[@]}"; do
    check "$SRC/$key" "$key"
done
check "$SCRATCH/xe_drm.h" xe_drm.h

mkdir -p "$HERE/include/drm" "$HERE/LICENSES"
for key in "${UPSTREAM_COPIES[@]}"; do
    cp "$SRC/$key" "$HERE/$key"
done
cp "$SCRATCH/xe_drm.h" "$HERE/include/drm/xe_drm.h"

{
    sed -n "${RANGES[0]/-/,}p" "$SRC/xf86drm.c"
    cat <<EOF

/*
 * Cellos libdrm-lite: generated by third_party/libdrm/update.sh from libdrm
 * $LIBDRM_PIN. Upstream bodies only, unmodified; device
 * enumeration (drmGetDevice*, drmFreeDevice*) is libs/drm-cellos/src/device.c.
 * Every other libdrm entry point is absent, so a new caller fails at link.
 */

#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>

#include "xf86drm.h"
#include "libdrm_macros.h"
EOF
    for range in "${RANGES[@]:1}"; do
        echo
        echo "/* upstream xf86drm.c:$range */"
        sed -n "${range/-/,}p" "$SRC/xf86drm.c"
    done
} > "$HERE/xf86drm.c"

echo "libdrm subset regenerated at $LIBDRM_PIN (xe_drm.h from Linux $LINUX_PIN)"
